<span class="line"><span style="color:#E06C75;">      permissions</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">Array</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">from</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">selected</span><span style="color:#ABB2BF;">),  </span><span style="color:#7F848E;font-style:italic;">// Set → Array</span></span>
